"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { useCaretRestore } from "@/hooks/use-caret-restore"
import { useControllableState } from "@/hooks/use-controllable-state"
import { toRmbUppercase } from "@/lib/chinese-number"
import { formatStat } from "@/lib/data-display"

import {
  AmountInputReadout,
  amountInputControlVariants,
} from "./amount-input-parts"
import { DEFAULT_LABELS } from "./config"
import type { AmountInputProps } from "./types"
import {
  compareAmount,
  finalizeText,
  formatAmount,
  sameAmount,
  sanitizeAmount,
  textToValue,
  toDecimalString,
  type SanitizeOptions,
} from "./utils"

/** 读屏播报大写的防抖时间（毫秒）：停手这么久才报一次，敲字过程中不打断读屏。 */
const ANNOUNCE_DELAY = 800

/** 软键盘弹出后最多等这么久（毫秒）再检查读数行有没有被挡住 */
const KEYBOARD_WAIT = 600

/**
 * 触屏设备上聚焦后，浏览器只保证输入框本身露出来，下面的大写行和错误提示常被软键盘挡住。
 * 等键盘弹出（visualViewport 缩小）后，把整个组件的底边滚到可见区域里。
 */
function revealBelowKeyboard(root: HTMLElement | null) {
  const viewport = window.visualViewport
  if (!root || !viewport || !window.matchMedia("(pointer: coarse)").matches)
    return
  // 键盘是动画弹出的，resize 会连发几次：停下来 150ms 再量；一直没有 resize（外接键盘、桌面触屏）就到点量一次
  let timer = window.setTimeout(check, KEYBOARD_WAIT)
  const settle = () => {
    window.clearTimeout(timer)
    timer = window.setTimeout(check, 150)
  }
  function check() {
    viewport!.removeEventListener("resize", settle)
    const bottom = root!.getBoundingClientRect().bottom
    const visibleBottom = viewport!.offsetTop + viewport!.height
    const overflow = bottom - visibleBottom + 12
    if (overflow > 0) window.scrollBy({ top: overflow, behavior: "smooth" })
  }
  viewport.addEventListener("resize", settle)
}

/** 金额输入框：实时千分位、光标不乱跳，下方同步显示人民币大写与大数估读。 */
function AmountInput({
  value: valueProp,
  defaultValue = "",
  onValueChange,
  min,
  max,
  decimals: decimalsProp = 2,
  symbol = "¥",
  label,
  variant = "bar",
  size = "default",
  showUppercase = true,
  showApproximate = true,
  approximateFrom = 10_000,
  readoutPlacement = "below",
  error,
  padDecimals = true,
  labels: labelsProp,
  className,
  id: idProp,
  name,
  form,
  disabled,
  readOnly,
  placeholder,
  inputMode,
  "aria-invalid": ariaInvalid,
  "aria-describedby": describedByProp,
  onFocus,
  onBlur,
  onKeyDown,
  ref,
  ...props
}: AmountInputProps) {
  const labels = { ...DEFAULT_LABELS, ...labelsProp }
  const decimals = Math.max(0, Math.floor(decimalsProp))
  const minText = min === undefined ? undefined : toDecimalString(min)
  const maxText = max === undefined ? undefined : toDecimalString(max)
  const allowNegative = minText !== undefined && minText.startsWith("-")
  const options: SanitizeOptions = { decimals, allowNegative }

  const autoId = React.useId()
  const id = idProp ?? autoId
  const inputRef = React.useRef<HTMLInputElement>(null)
  const rootRef = React.useRef<HTMLDivElement>(null)
  React.useImperativeHandle(ref, () => inputRef.current as HTMLInputElement)

  const [value, setValue] = useControllableState({
    prop: valueProp,
    defaultProp: defaultValue,
    onChange: onValueChange,
  })
  const [focused, setFocused] = React.useState(false)
  const [touched, setTouched] = React.useState(false)
  const [text, setText] = React.useState(() =>
    formatAmount(value, options, padDecimals),
  )
  // 外部改了 value（受控）才同步显示文本；内部输入产生的变化文本已经是最新的，不会触发。
  // 只在 value 变化的那一次比较，避免 value 的位数超过 decimals 时反复改写
  const [seenValue, setSeenValue] = React.useState(value)
  if (seenValue !== value) {
    setSeenValue(value)
    if (!sameAmount(value, textToValue(text)))
      setText(formatAmount(value, options, padDecimals && !focused))
  }

  // 整理后要恢复的光标位置；每次都是新对象，保证即使文本没变（敲了非法字符）也会重设光标
  const setCaret = useCaretRestore(inputRef)

  const composing = React.useRef(false)
  const [edits, setEdits] = React.useState(0)

  const commit = (raw: string, rawCaret: number) => {
    const next = sanitizeAmount(raw, rawCaret, options)
    setText(next.text)
    setCaret({ position: next.caret })
    setValue(textToValue(next.text))
    setEdits((count) => count + 1)
  }

  const amount = textToValue(text)
  const numeric = amount === "" ? 0 : Number(amount)
  const uppercase = showUppercase && amount !== "" ? toRmbUppercase(amount) : ""
  const approximate =
    showApproximate && amount !== "" && Math.abs(numeric) >= approximateFrom
      ? `${labels.approximate} ${formatStat(numeric, { digits: 1 })}`
      : ""

  // 越界：超过 max 立即提示（再敲只会更大）；低于 min 要等失焦，否则敲第一位数字就报错。
  // 无论提示与否，越界值都通过 setCustomValidity 拦住表单提交
  const tooLow =
    amount !== "" && minText !== undefined && compareAmount(amount, minText) < 0
  const tooHigh =
    amount !== "" && maxText !== undefined && compareAmount(amount, maxText) > 0
  const limitText = (limit: string) => {
    const digits = Math.max(decimals, limit.split(".")[1]?.length ?? 0)
    const formatted = formatAmount(
      limit,
      { decimals: digits, allowNegative: true },
      true,
    )
    return `${typeof symbol === "string" ? symbol : ""}${formatted}`
  }
  const rangeMessage = tooHigh
    ? labels.aboveMax.replace("{max}", limitText(maxText!))
    : tooLow
      ? labels.belowMin.replace("{min}", limitText(minText!))
      : ""
  React.useEffect(() => {
    inputRef.current?.setCustomValidity(rangeMessage)
  }, [rangeMessage])

  const errorMessage = error || (tooHigh || touched ? rangeMessage : "")
  const invalid =
    Boolean(errorMessage) || ariaInvalid === true || ariaInvalid === "true"

  // 读屏：大写行通过 aria-describedby 在聚焦时朗读；敲字时不逐字播报，
  // 停手 ANNOUNCE_DELAY 毫秒后用 polite 的状态区报一次最新的大写
  const [announcement, setAnnouncement] = React.useState("")
  React.useEffect(() => {
    if (edits === 0 || !focused) return
    const timer = window.setTimeout(
      () =>
        setAnnouncement(uppercase ? `${labels.uppercase} ${uppercase}` : ""),
      ANNOUNCE_DELAY,
    )
    return () => window.clearTimeout(timer)
  }, [edits, focused, uppercase, labels.uppercase])

  // 非受控的表单重置：回到 defaultValue。监听器只挂一次，通过 ref 拿到最新的设置
  const resetRef = React.useRef(() => {})
  React.useEffect(() => {
    resetRef.current = () => {
      setText(formatAmount(defaultValue, options, padDecimals))
      setValue(defaultValue)
    }
  })
  const controlled = valueProp !== undefined
  React.useEffect(() => {
    const element = inputRef.current?.form
    if (!element || controlled) return
    // reset 事件在表单清空之前触发，等一帧再覆盖
    const reset = () => window.setTimeout(() => resetRef.current())
    element.addEventListener("reset", reset)
    return () => element.removeEventListener("reset", reset)
  }, [controlled])

  const uppercaseId = `${id}-uppercase`
  const errorId = `${id}-error`
  const describedBy =
    [
      describedByProp,
      showUppercase && uppercase ? uppercaseId : undefined,
      errorMessage ? errorId : undefined,
    ]
      .filter(Boolean)
      .join(" ") || undefined

  const display = variant === "display"
  const labelNode = label ? (
    <label
      data-slot="amount-input-label"
      htmlFor={id}
      className={
        display
          ? "text-sm text-muted-foreground"
          : "mr-auto shrink-0 text-muted-foreground max-md:text-sm"
      }
    >
      {label}
    </label>
  ) : null

  const readout =
    showUppercase || approximate ? (
      <AmountInputReadout
        uppercase={uppercase}
        uppercaseId={uppercaseId}
        uppercaseLabel={labels.uppercase}
        placeholder={labels.uppercasePlaceholder}
        showUppercase={showUppercase}
        approximate={approximate}
        // 大字时去掉虚线框，读数就是金额下面的一行小字
        className={display ? "border-0 bg-transparent px-0" : undefined}
      />
    ) : null

  return (
    <div
      ref={rootRef}
      data-slot="amount-input"
      data-variant={variant}
      data-size={size}
      data-invalid={invalid ? "" : undefined}
      data-disabled={disabled ? "" : undefined}
      data-readonly={readOnly ? "" : undefined}
      className={cn("flex w-full flex-col gap-1.5", !display && "in-data-[slot=grid-toolbar]:h-full", className)}
    >
      {display && labelNode}
      {readoutPlacement === "above" && readout}
      <div
        data-slot="amount-input-control"
        className={cn(
          amountInputControlVariants({ variant, size }),
          display
            ? invalid
              ? "border-destructive"
              : "border-edge focus-within:border-primary"
            : invalid
              ? "border-destructive ring-3 ring-destructive/20 dark:border-destructive/50 dark:ring-destructive/40"
              : "border-edge focus-within:border-foreground/25 focus-within:bg-background hover:not-focus-within:bg-muted dark:focus-within:bg-input/30",
          disabled && "cursor-not-allowed opacity-50",
          readOnly && (display ? "border-dashed" : "bg-muted/30"),
        )}
        // 点到条内空白处（标签与数字之间）也聚焦输入框
        onMouseDown={(event) => {
          if (event.target === event.currentTarget) {
            event.preventDefault()
            inputRef.current?.focus()
          }
        }}
      >
        {!display && labelNode}
        {symbol != null && (
          <span
            data-slot="amount-input-symbol"
            aria-hidden="true"
            className={cn(
              "shrink-0 text-muted-foreground select-none",
              // 大字时符号小一号、和数字底部对齐，像收银台上的金额
              display && "text-[0.6em] font-medium",
            )}
          >
            {symbol}
          </span>
        )}
        <input
          {...props}
          ref={inputRef}
          id={id}
          data-slot="amount-input-input"
          type="text"
          inputMode={
            inputMode ??
            (allowNegative ? "text" : decimals > 0 ? "decimal" : "numeric")
          }
          autoComplete="off"
          spellCheck={false}
          value={text}
          placeholder={
            placeholder ?? (decimals > 0 ? `0.${"0".repeat(decimals)}` : "0")
          }
          disabled={disabled}
          readOnly={readOnly}
          aria-invalid={invalid || undefined}
          aria-describedby={describedBy}
          className={cn(
            "min-w-0 bg-transparent tabular-nums outline-none placeholder:font-normal placeholder:text-muted-foreground/60 disabled:cursor-not-allowed",
            display
              ? "flex-1 py-0.5 leading-tight font-semibold"
              : // 有条内标签时金额靠右，与方条开关、数值滑块的「左标签右数值」一致；
                // 输入框按内容收窄，货币符号才会贴着金额而不是贴着标签
                cn(
                  "h-full font-medium",
                  label
                    ? "field-sizing-content max-w-full text-right"
                    : "flex-1",
                ),
          )}
          onChange={(event) => {
            const input = event.currentTarget
            // 输入法组词期间不整理，否则会打断候选词；组词结束时再统一处理
            if (composing.current) return setText(input.value)
            commit(input.value, input.selectionStart ?? input.value.length)
          }}
          onCompositionStart={() => {
            composing.current = true
          }}
          onCompositionEnd={(event) => {
            composing.current = false
            const input = event.currentTarget
            commit(input.value, input.selectionStart ?? input.value.length)
          }}
          onKeyDown={(event) => {
            onKeyDown?.(event)
            const input = event.currentTarget
            const { selectionStart: start, selectionEnd: end } = input
            if (
              event.defaultPrevented ||
              composing.current ||
              disabled ||
              readOnly ||
              start === null ||
              start !== end ||
              event.altKey ||
              event.ctrlKey ||
              event.metaKey
            )
              return
            // 光标紧贴千分位逗号时，退格 / 删除越过逗号去删旁边的数字，
            // 否则只删了逗号、整理后又长回来，用户会觉得按键没反应
            const current = input.value
            if (event.key === "Backspace" && current[start - 1] === ",") {
              event.preventDefault()
              commit(
                current.slice(0, start - 2) + current.slice(start),
                start - 2,
              )
            } else if (event.key === "Delete" && current[start] === ",") {
              event.preventDefault()
              commit(current.slice(0, start) + current.slice(start + 2), start)
            }
          }}
          onFocus={(event) => {
            setFocused(true)
            revealBelowKeyboard(rootRef.current)
            onFocus?.(event)
          }}
          onBlur={(event) => {
            setFocused(false)
            setTouched(true)
            const finished = finalizeText(text, decimals, padDecimals)
            if (finished !== text) {
              setText(finished)
              setValue(textToValue(finished))
            }
            onBlur?.(event)
          }}
        />
      </div>
      {readoutPlacement === "below" && readout}
      {errorMessage && (
        <p
          id={errorId}
          data-slot="amount-input-error"
          className="text-xs text-destructive"
        >
          {errorMessage}
        </p>
      )}
      {name && (
        <input
          type="hidden"
          data-slot="amount-input-value"
          name={name}
          form={form}
          value={amount}
          disabled={disabled}
        />
      )}
      <span data-slot="amount-input-status" role="status" className="sr-only">
        {announcement}
      </span>
    </div>
  )
}

export { AmountInput, amountInputControlVariants }
export type {
  AmountInputProps,
  AmountInputSize,
  AmountInputVariant,
} from "./types"

import * as React from "react"
import { cva } from "class-variance-authority"

import { cn } from "@/lib/utils"
import { barFieldVariants } from "@/components/ui/bar-field/bar-field"

/**
 * 两种外观：
 * - `bar` 方条：与方条开关、分段选择同一套（浅灰底、细边框、标签在条内左侧），放进同一个面板里能对齐。
 *   高度只来自既有三档 28 / 32 / 36px，触屏设备上各加高一档（36 / 40 / 44px）
 * - `display` 大字：付款、转账页上的主金额，数字放大、下面一道横线，标签写在上方
 * 手机上字号至少 16px，iOS 聚焦时才不会自动放大页面
 */
const amountInputControlVariants = cva(
  "flex w-full min-w-0 cursor-text transition-colors",
  {
    variants: {
      variant: {
        bar: "",
        display: "items-baseline gap-1 border-b-2 pb-1 tracking-tight",
      },
      size: { sm: "", default: "", lg: "" },
    },
    compoundVariants: [
      {
        variant: "bar",
        size: "sm",
        class: cn(barFieldVariants({ size: "sm" }), "gap-1.5"),
      },
      {
        variant: "bar",
        size: "default",
        class: cn(barFieldVariants({ size: "default" }), "gap-1.5"),
      },
      {
        variant: "bar",
        size: "lg",
        class: cn(barFieldVariants({ size: "lg" }), "gap-1.5"),
      },
      { variant: "display", size: "sm", class: "text-2xl" },
      { variant: "display", size: "default", class: "text-3xl" },
      { variant: "display", size: "lg", class: "text-4xl" },
    ],
    defaultVariants: { variant: "bar", size: "default" },
  },
)

function AmountInputReadout({
  className,
  uppercase,
  uppercaseId,
  uppercaseLabel,
  placeholder,
  showUppercase,
  approximate,
  ...props
}: Omit<React.ComponentProps<"div">, "children"> & {
  /** 人民币大写；空串时显示 `placeholder` */
  uppercase: string
  uppercaseId: string
  uppercaseLabel: string
  placeholder: string
  showUppercase: boolean
  /** 大数估读，如「约 1.2万」；空串不显示 */
  approximate: string
}) {
  return (
    <div
      data-slot="amount-input-readout"
      className={cn(
        "flex items-start justify-between gap-x-3 gap-y-0.5 rounded-md border border-dashed border-edge bg-muted/30 px-2.5 py-1.5 text-xs max-sm:flex-wrap",
        className,
      )}
      {...props}
    >
      {showUppercase && (
        <p
          id={uppercaseId}
          data-slot="amount-input-uppercase"
          className="min-w-0 flex-1 leading-5 break-words"
        >
          <span className="mr-2 text-muted-foreground">{uppercaseLabel}</span>
          {uppercase ? (
            <span className="font-medium text-foreground">{uppercase}</span>
          ) : (
            <span className="text-muted-foreground/70">{placeholder}</span>
          )}
        </p>
      )}
      {approximate && (
        <p
          data-slot="amount-input-approximate"
          className="shrink-0 leading-5 text-muted-foreground tabular-nums"
        >
          {approximate}
        </p>
      )}
    </div>
  )
}

export { AmountInputReadout, amountInputControlVariants }

/**
 * 金额输入的纯函数：把「用户敲出来的任意文本」整理成千分位文本，并算出整理后光标该在哪。
 * 全程按十进制字符串处理，不转 number，所以万亿级金额和 `0.1 + 0.2` 都不会丢精度。
 */

/** 整数部分最多 16 位，与 chinese-number 的大写范围一致。 */
const MAX_INTEGER_DIGITS = 16

type SanitizeOptions = {
  /** 小数位上限；0 表示只能输入整数 */
  decimals: number
  /** 是否允许开头的负号 */
  allowNegative: boolean
}

type Sanitized = {
  /** 带千分位的显示文本 */
  text: string
  /** 整理后光标所在的位置 */
  caret: number
}

/** 全角数字、全角小数点、各种减号统一成 ASCII；其余字符（逗号、空格、¥、字母）返回空串丢掉。 */
function normalizeChar(ch: string) {
  const code = ch.charCodeAt(0)
  if (code >= 0xff10 && code <= 0xff19)
    return String.fromCharCode(code - 0xfee0)
  if (/[0-9.]/.test(ch)) return ch
  if ("．。｡".includes(ch)) return "."
  if ("-－−﹣‐–".includes(ch)) return "-"
  return ""
}

function groupInteger(int: string) {
  return int.replace(/\B(?=(\d{3})+(?!\d))/g, ",")
}

/**
 * 整理输入文本，同时换算光标。
 *
 * 光标算法：数出光标左边有几个「有效字符」（数字、小数点、负号，逗号不算），整理完后
 * 在新文本里找到第 n 个有效字符，把光标放在它后面。千分位逗号的增减不影响有效字符个数，
 * 所以在中间插入、删除、粘贴之后光标都留在用户眼里「同一个位置」。
 * 被丢掉的字符（非法字符、超出的小数位）不计数；开头多余的零被后来的数字顶替时，
 * 被顶替的零也一并不计，这样 `0|` 再敲 `5` 得到 `5|`。
 */
function sanitizeAmount(
  raw: string,
  caret: number,
  { decimals, allowNegative }: SanitizeOptions,
): Sanitized {
  const kept: { ch: string; before: boolean }[] = []
  let negative = false
  let hasDot = false
  let int = ""
  let frac = ""

  for (let i = 0; i < raw.length; i++) {
    const ch = normalizeChar(raw[i])
    const before = i < caret
    if (ch === "-") {
      if (allowNegative && kept.length === 0) {
        negative = true
        kept.push({ ch, before })
      }
    } else if (ch === ".") {
      if (decimals > 0 && !hasDot) {
        hasDot = true
        // 直接敲 ".5" 补成 "0.5"，补出来的 0 算在小数点所在的一侧
        if (int === "") {
          int = "0"
          kept.push({ ch: "0", before })
        }
        kept.push({ ch, before })
      }
    } else if (ch) {
      if (hasDot) {
        if (frac.length < decimals) {
          frac += ch
          kept.push({ ch, before })
        }
      } else if (int === "0") {
        // 前导零只留一个：0 后面再敲数字就顶替它
        if (ch !== "0") {
          kept.pop()
          int = ch
          kept.push({ ch, before })
        }
      } else if (int.length < MAX_INTEGER_DIGITS) {
        int += ch
        kept.push({ ch, before })
      }
    }
  }

  const text = `${negative ? "-" : ""}${groupInteger(int)}${hasDot ? `.${frac}` : ""}`
  const count = kept.filter((token) => token.before).length
  let position = 0
  if (count > 0) {
    position = text.length
    let seen = 0
    for (let i = 0; i < text.length; i++) {
      if (text[i] !== "," && ++seen === count) {
        position = i + 1
        break
      }
    }
  }
  return { text, caret: position }
}

/** 显示文本 → 原始数值字符串：去千分位、去末尾小数点；空和单独的负号都是 `""`，`-0` 归一成 `0`。 */
function textToValue(text: string) {
  let value = text.replace(/,/g, "")
  if (value === "" || value === "-") return ""
  if (value.endsWith(".")) value = value.slice(0, -1)
  if (/^-0*(\.0*)?$/.test(value)) value = value.slice(1)
  return value
}

/** 失焦时收尾：补齐小数位（或去掉悬空的小数点）；只剩一个负号就清空。 */
function finalizeText(text: string, decimals: number, pad: boolean) {
  if (text === "" || text === "-") return ""
  if (decimals > 0 && pad) {
    const [int, frac = ""] = text.split(".")
    return `${int}.${frac.padEnd(decimals, "0")}`
  }
  return text.endsWith(".") ? text.slice(0, -1) : text
}

/** 把外部传入的数值字符串整理成显示文本（`pad` 为真时补齐小数位）。 */
function formatAmount(value: string, options: SanitizeOptions, pad: boolean) {
  const { text } = sanitizeAmount(value, 0, options)
  return finalizeText(text, options.decimals, pad)
}

/** 两个十进制字符串按数值比较：`1234.50` 与 `1234.5` 相等，不经过浮点。 */
function compareAmount(a: string, b: string) {
  const x = splitAmount(a)
  const y = splitAmount(b)
  if (x.negative !== y.negative) return x.negative ? -1 : 1
  const length = Math.max(x.frac.length, y.frac.length)
  const left =
    x.int.padStart(Math.max(x.int.length, y.int.length), "0") +
    x.frac.padEnd(length, "0")
  const right =
    y.int.padStart(Math.max(x.int.length, y.int.length), "0") +
    y.frac.padEnd(length, "0")
  const order = left === right ? 0 : left < right ? -1 : 1
  return x.negative ? -order : order
}

/** 拆成符号、整数、小数（去掉末尾的零）；零不带符号。 */
function splitAmount(value: string) {
  const [int = "", frac = ""] = value.replace("-", "").split(".")
  const parts = { int: int.replace(/^0+/, ""), frac: frac.replace(/0+$/, "") }
  return {
    ...parts,
    negative: value.startsWith("-") && (parts.int !== "" || parts.frac !== ""),
  }
}

function sameAmount(a: string, b: string) {
  if (a === "" || b === "") return a === b
  return compareAmount(a, b) === 0
}

/** `min` / `max` 允许传 number 或字符串，统一成不带科学计数法的十进制字符串。 */
function toDecimalString(value: number | string) {
  if (typeof value === "string") return value.replace(/,/g, "").trim()
  return value.toLocaleString("en-US", {
    useGrouping: false,
    maximumFractionDigits: 20,
  })
}

